const config = $input.first().json;
if (!Array.isArray(config.keywords) || !config.keywords.length || config.keywords.length > 20) {
  throw new Error('Enter 1–20 keywords. Each unique keyword makes one paid search request.');
}
const keywords = [...new Set(config.keywords.map(value => {
  if (typeof value !== 'string' || !value.trim() || value.trim().length > 2000) {
    throw new Error('Each keyword must contain 1–2000 characters.');
  }
  return value.trim();
}))];
function domain(value) {
  if (typeof value !== 'string') throw new Error('Use bare domains, such as example.com.');
  const host = value.trim().toLowerCase().replace(/^www\./, '').replace(/\.$/, '');
  if (host.length > 253 || !/^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(host)) {
    throw new Error('Use bare ASCII/punycode domains without protocols, paths or ports.');
  }
  return host;
}
const target = domain(config.target_domain);
if (!Array.isArray(config.competitor_domains) || !config.competitor_domains.length || config.competitor_domains.length > 5) {
  throw new Error('Enter 1–5 competitor domains.');
}
const competitors = [...new Set(config.competitor_domains.map(domain))];
const domains = [target, ...competitors];
for (let i = 0; i < domains.length; i++) {
  for (let j = i + 1; j < domains.length; j++) {
    if (domains[i] === domains[j] || domains[i].endsWith('.' + domains[j]) || domains[j].endsWith('.' + domains[i])) {
      throw new Error('Tracked domains must be distinct and must not overlap as parent/subdomains.');
    }
  }
}
const country = String(config.country ?? '').trim().toLowerCase();
const language = String(config.language ?? '').trim().toLowerCase();
if (!/^[a-z]{2}$/.test(country)) throw new Error('Set a two-letter country code.');
if (!/^[a-z0-9-]{1,35}$/.test(language)) throw new Error('Set a valid language code.');
if (!Number.isInteger(config.result_count) || config.result_count < 1 || config.result_count > 100) {
  throw new Error('result_count must be an integer from 1 to 100.');
}
return keywords.map(query => ({ json: {
  query, target_domain: target, competitor_domains: competitors,
  country, language, result_count: config.result_count,
  planned_paid_queries: keywords.length,
} }));

const inputs = $('Validate keywords and domains').all().map(item => item.json);
const responses = $input.all();
if (inputs.length !== responses.length) throw new Error('Search response count does not match the keyword list.');
function hostOf(value) {
  if (typeof value !== 'string') return null;
  const match = /^https?:\/\/([^/?#]+)(?:[/?#]|$)/i.exec(value);
  if (!match || match[1].includes('@')) return null;
  const host = match[1].replace(/:\d+$/, '').toLowerCase().replace(/^www\./, '').replace(/\.$/, '');
  return /^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(host) ? host : null;
}
const audits = responses.map((item, index) => {
  const settings = inputs[index];
  const envelope = item.json;
  const result = envelope.results?.[0];
  if (envelope.error || envelope.status !== 'done' || !Array.isArray(result?.organic)) {
    throw new Error('Expected a completed Google Search response with an organic array; inspect the Fetch node before retrying.');
  }
  const domains = [settings.target_domain, ...settings.competitor_domains];
  let invalidUrls = 0;
  const unique = new Map();
  for (const row of result.organic) {
    const host = hostOf(row.link);
    if (!host) { invalidUrls++; continue; }
    const url = row.link.split('#')[0];
    const position = Number.isInteger(row.position) && row.position > 0 ? row.position : null;
    const match = domains.find(d => host === d || host.endsWith('.' + d)) ?? '';
    const entry = { position, domain: host, matched_domain: match, role: match === settings.target_domain ? 'target' : match ? 'competitor' : 'other', title: row.title ?? '', url, snippet: row.snippet ?? '' };
    const previous = unique.get(url);
    if (!previous || (position !== null && (previous.position === null || position < previous.position))) unique.set(url, entry);
  }
  const evidence = [...unique.values()].sort((a, b) => (a.position ?? Infinity) - (b.position ?? Infinity));
  const positions = domains.map(domain => {
    const matches = evidence.filter(row => row.matched_domain === domain);
    const ranked = matches.filter(row => row.position !== null);
    return { domain, role: domain === settings.target_domain ? 'target' : 'competitor', observed: matches.length > 0, position: ranked[0]?.position ?? null, url: ranked[0]?.url ?? matches[0]?.url ?? '', title: ranked[0]?.title ?? matches[0]?.title ?? '', matching_pages: matches.length, unknown_positions: matches.filter(row => row.position === null).length };
  });
  const target = positions[0];
  const competitors = positions.slice(1);
  const best = competitors.filter(row => row.position !== null).sort((a, b) => a.position - b.position)[0];
  let finding, action;
  if (result.organic.length === 0) {
    finding = 'no_organic_results'; action = 'Check the keyword and search settings; no ranking conclusion is available.';
  } else if (invalidUrls || positions.some(row => row.unknown_positions > 0)) {
    finding = 'incomplete_result_fields'; action = 'Inspect source results with invalid URLs or missing positions before comparing.';
  } else if (!target.observed && best) {
    finding = 'competitor_visible_target_not_found'; action = 'Review the competing page and your relevant landing page; the target was not found in this returned result set.';
  } else if (target.position !== null && best && best.position < target.position) {
    finding = 'competitor_ahead'; action = 'Compare the linked pages and search intent before deciding whether to improve your page.';
  } else if (target.position !== null) {
    finding = 'target_leads_tracked_competitors'; action = 'Keep this snapshot as a reference; no tracked competitor has a better known position.';
  } else {
    finding = 'no_tracked_domains_found'; action = 'Review the other ranking domains and confirm that the chosen competitors are relevant.';
  }
  return {
    query: settings.query, country: settings.country, language: settings.language, requested_count: settings.result_count,
    returned_count: result.organic.length, unique_valid_urls: evidence.length, invalid_url_count: invalidUrls,
    captured_at: envelope.created_at ?? null, credits: typeof envelope.usage?.credits === 'number' ? envelope.usage.credits : null,
    target_domain: target.domain, target_position: target.position, target_url: target.url,
    best_competitor_domain: best?.domain ?? '', best_competitor_position: best?.position ?? null, best_competitor_url: best?.url ?? '',
    position_gap: target.position !== null && best ? target.position - best.position : null,
    finding, suggested_review: action, search_parameters_returned: result.searchParameters ?? null, domains: positions, evidence,
  };
});
const order = ['competitor_visible_target_not_found', 'competitor_ahead', 'incomplete_result_fields', 'no_tracked_domains_found', 'no_organic_results', 'target_leads_tracked_competitors'];
audits.sort((a, b) => order.indexOf(a.finding) - order.indexOf(b.finding));
return [{ json: {
  source: 'google_search', scope: 'One requested page per unique keyword; observed organic positions only.',
  requests: audits.length, total_credits: audits.every(row => row.credits !== null) ? audits.reduce((sum, row) => sum + row.credits, 0) : null,
  review_candidates: audits.filter(row => ['competitor_visible_target_not_found', 'competitor_ahead'].includes(row.finding)).length,
  limitations: 'A missing domain is not proof of deindexing or a content gap. No search volume, full-page analysis, historical changes or ranking guarantees. created_at is collection time, not publication time.',
  keywords: audits,
} }];

// Prefix spreadsheet formulas in untrusted text before CSV export. JSON keeps the original values.
const safeText = value => typeof value === 'string' && /^[\s]*[=+@-]/.test(value) ? "'" + value : value;
return $input.first().json.keywords.map(row => ({ json: Object.fromEntries(Object.entries({
  query: row.query, finding: row.finding, target_domain: row.target_domain,
  target_position: row.target_position, best_competitor_domain: row.best_competitor_domain,
  best_competitor_position: row.best_competitor_position, position_gap: row.position_gap,
  target_url: row.target_url, best_competitor_url: row.best_competitor_url,
  country: row.country, language: row.language, requested_count: row.requested_count,
  returned_count: row.returned_count, captured_at: row.captured_at, credits: row.credits,
  suggested_review: row.suggested_review,
}).map(([key, value]) => [key, safeText(value)])) }));
